function ServiceTier({ tier, locale }: { tier: ServiceTierData; locale: Locale }) {
  const isEnterprise = tier.id === "enterprise";

  return (
    <article
      className={`rounded-[24px] border ${
        isEnterprise
          ? "border-[#111111] bg-[#111111] p-8 md:p-14"
          : "border-[#d9d6cf] bg-white p-7 md:p-10"
      }`}
    >
      <div className="mb-5 flex flex-wrap items-center gap-3">
        <span className={`inline-flex rounded-full border px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.12em] ${
          isEnterprise
            ? "border-[#ffffff30] bg-[#ffffff10] text-[#ffffff99]"
            : "border-[#cbc7be] bg-[#f8f8f6] text-[#5f5f5a]"
        }`}>
          {tier.id}
        </span>
        {tier.selective ? (
          <span className={`inline-flex rounded-full border px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.12em] ${
            isEnterprise
              ? "border-[#ff5a1f] text-[#ff5a1f]"
              : "border-[#111111] text-[#111111]"
          }`}>
            {locale === "no" ? "Selektiv leveranse" : "Selective engagement"}
          </span>
        ) : null}
      </div>

      <h3 className={`font-[var(--font-heading)] text-2xl font-semibold leading-tight tracking-tight ${
        isEnterprise ? "text-white" : "text-[#111111]"
      }`}>
        {pick(locale, tier.label)}
      </h3>

      {tier.headline ? (
        <p className={`mt-4 max-w-3xl font-[var(--font-heading)] text-[1.35rem] font-medium leading-snug tracking-tight md:text-[1.75rem] ${
          isEnterprise ? "text-white" : "text-[#111111]"
        }`}>
          {pick(locale, tier.headline)}
        </p>
      ) : null}

      <ul className={`mt-8 grid gap-2.5 text-sm md:max-w-3xl ${
        isEnterprise ? "md:grid-cols-2" : ""
      }`}>
        {tier.points.map((point, index) => (
          <li key={`${tier.id}-point-${index}`} className="flex items-start gap-2">
            <span className="mt-[0.38rem] h-1.5 w-1.5 shrink-0 rounded-full bg-[#ff5a1f]" aria-hidden="true" />
            <span className={isEnterprise ? "text-[#ffffffcc]" : "text-[#111111]"}>{pick(locale, point)}</span>
          </li>
        ))}
      </ul>

      <div className={`mt-8 grid gap-4 text-[15px] leading-relaxed md:max-w-4xl ${
        isEnterprise ? "text-[#ffffff99]" : "text-[#5f5f5a]"
      }`}>
        {tier.body.map((paragraph, index) => (
          <p key={`${tier.id}-body-${index}`} style={{ whiteSpace: "pre-line" }}>{pick(locale, paragraph)}</p>
        ))}
      </div>

      <a
        href="#lead-form"
        className={`mt-10 inline-flex h-12 items-center rounded-full px-7 text-sm font-semibold transition-all ${
          isEnterprise
            ? "bg-[#ff5a1f] text-white hover:bg-[#e5521c]"
            : "border border-[#111111] bg-transparent text-[#111111] hover:bg-[#111111] hover:text-white"
        }`}
      >
        {pick(locale, tier.cta)}
      </a>
    </article>
  );
}

